function Form({onSave,children,submitLabel='Save',resetOnSuccess=false}:{submitLabel?:string;resetOnSuccess?:boolean;onSave:(v:FormData)=>Promise<void>;children:React.ReactNode}){const [busy,setBusy]=useState(false),[error,setError]=useState('');return <form autoComplete="off" className="op-form" onSubmit={async e=>{e.preventDefault();const form=e.currentTarget,data=new FormData(form);setError('');setBusy(true);try{await onSave(data);if(resetOnSuccess)form.reset()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}}><fieldset disabled={busy}>{children}{error&&<p className="op-red" role="alert">{error}</p>}<button className="op-primary" disabled={busy}>{busy?'Saving…':submitLabel}</button></fieldset></form>}
function Input({name,label,value='',type='text',required=false,...rest}:any){return <label>{label}<input autoComplete="off" name={name} type={type} defaultValue={value??''} required={required} {...rest}/></label>}
function Select({name,label,value='',items,required=true}:any){return <label>{label}<select name={name} defaultValue={value} required={required}><option value="">{required?'Select…':'Unassigned / select later'}</option>{items.map((v:any)=><option key={v.id??v} value={v.id??v}>{v.name??v}</option>)}</select></label>}
function Text({name,label,value=''}:any){return <label>{label}<textarea name={name} defaultValue={value}/></label>}
function QualityValue({score}:any){return <span className={score!=null&&score<3.6?'op-red':'live-green'}>{score==null?'Not recorded':score.toFixed(2)}{score===4?' ★':''}<small>{score==null?'':score<3.6?'Poor':score<3.7?'Fair':score<3.8?'Good':'Outstanding'}</small></span>}

