 const current=jobs.find((j:any)=>j.id===selected),filtered=jobs.filter((j:any)=>[j.customer,j.number,j.address,j.crew].join(' ').toLowerCase().includes(query.toLowerCase()));
 const nav:any[]=[['Overview',LayoutDashboard],['Schedule',CalendarDays],...(['admin','supervisor'].includes(me.role)?[['Map',MapPin]]:[]),...(!installer?[['Jobs',FolderOpen],['Aging reports',Clock],['Approvals',ClipboardCheck],['Job visits',MapPin],['Quality',Star],['Installers',UsersRound]]:[]),...(me.role==='admin'?[['Connections',Plug]]:[]),['Settings',Settings]];
