function ScheduleForm({j,team,today,save,allowUnassigned=false}:any){const [day,setDay]=useState(j.install||today),[multi,setMulti]=useState(!!j.installEnd&&j.installEnd!==j.install),[end,setEnd]=useState(j.installEnd||j.install||today),[files,setFiles]=useState<File[]>([]);const late=(dayDifference(j.received,day)||0)>30;return <Form onSave={async f=>{const salesPhotos=[];for(const file of files)salesPhotos.push(await uploadAttachment(j.id,'photos',file));await save('schedule',{salesPhotos,date:day,endDate:multi?end:day,period:field(f,'time')?(Number(field(f,'time').slice(0,2))<12?'AM':'PM'):field(f,'period'),time:field(f,'time'),installerId:field(f,'installerId'),stop:Number(field(f,'stop')),additionalInstructions:field(f,'additionalInstructions'),instructions:field(f,'instructions')})}}><label className="op-check"><input type="checkbox" checked={multi} onChange={e=>setMulti(e.target.checked)}/>Multi-day</label>{multi&&<p className="op-muted">Scheduled Monday–Friday only. Weekends are skipped.</p>}<label>{multi?'Start date':'Install date'}<input type="date" required value={day} onChange={e=>{setDay(e.target.value);if(end<e.target.value)setEnd(e.target.value)}}/></label>{multi&&<label>End date<input type="date" min={day} value={end} required onChange={e=>setEnd(e.target.value)}/></label>}<Select label="AM / PM" name="period" value={j.installPeriod||'AM'} items={['AM','PM']}/><Select required={false} label="Start time (optional)" name="time" value={j.installTime||''} items={[{id:'',name:'Use AM / PM window'},...Array.from({length:24},(_,hour)=>{const id=String(hour).padStart(2,'0')+':00';return {id,name:hourLabel(id)}})]}/><Select required={!allowUnassigned} label={allowUnassigned?"Installer (optional — assign later)":"Installer"} name="installerId" value={j.installerId} items={team.filter((m:any)=>m.role==='installer'&&m.active!==0)}/><Input label="Stop number" name="stop" type="number" min="1" max="99" value={j.stopNumber||1} required/><label>Additional sales photos<input type="file" multiple accept="image/*" onChange={e=>setFiles(Array.from(e.target.files||[]))}/></label><Text name="instructions" label="Job instructions (visible to installer)" value={j.instructions}/><Text name="additionalInstructions" label="Additional scheduling instructions" value={j.scheduleInstructions}/>{!j.noPermitRequired&&!(j.permitReceived&&j.permitNumber)&&<p className="op-red">Mark No Permit Required, or enter Permit Received and a permit number before scheduling.</p>}{day<today&&<p className="op-callout">Recording a past installation date. This does not change the job status or aging start date.</p>}{late&&<p className="op-callout">This appointment is beyond 30 days received. Scheduling is allowed regardless of payment balance; the aging timer continues until the job status changes.</p>}</Form>}
