function AdminResultForm({j,save}:any){const [target,setTarget]=useState('Incomplete');return <details className="op-disclosure"><summary>Admin result override · INC / COMP</summary><p>Move this job without the required photos or documents. A reason is required and the exception is recorded in job history.</p><Form onSave={async f=>{if(target==='Closed'&&!window.confirm('Are you sure you want to close this job?'))return;await save('adminResult',{target,reason:field(f,'reason'),reorder:field(f,'reorder'),reorderDate:field(f,'reorderDate'),confirmed:true})}}><label>Result<select value={target} onChange={e=>setTarget(e.target.value)}><option value="Incomplete">INC — Mark incomplete</option><option value="Closed">COMP — Close job</option></select></label>{target==='Incomplete'&&<><label>Reorder information<textarea name="reorder" defaultValue={j.reorder||''} required/></label><Input name="reorderDate" label="Reorder date · starts INC aging" type="date" value={j.reorderDate||localDay()} max={localDay()} required/></>}<Input name="reason" label={target==='Incomplete'?'Required reason for moving to INC without photos':'Reason for override'} required/></Form></details>}
