function InstallerReport({j,save}:any){const [status,setStatus]=useState('Complete'),[attachments,setAttachments]=useState<any[]>([]),[busy,setBusy]=useState(false),[error,setError]=useState('');const requirements=requiredReportKinds(status);const upload=async(kind:string,files:File[])=>{if(!files.length)return;setBusy(true);setError('');try{const uploaded:any[]=[];for(const file of files)uploaded.push(await uploadAttachment(j.id,kind,file));setAttachments(old=>['issue','photos'].includes(kind)?[...old,...uploaded]:[...old.filter(v=>v.kind!==kind),uploaded[0]])}catch(e){setError((e as Error).message)}finally{setBusy(false)}};return <><div className="live-requirements"><strong>{status} requires:</strong><span>Front photo</span><span>Back photo</span><span>Left-side photo</span><span>Right-side photo</span><span>{status==='Complete'?'Completion certificate':'Incomplete certificate'}</span>{status==='Incomplete'&&<span>One or more issue photos</span>}</div><Form onSave={async f=>{if(busy)throw Error('Wait for the upload to finish.');const missing=requirements.find(kind=>!attachments.some(a=>a.kind===kind));if(missing)throw Error(`Add ${reportLabels[missing].toLowerCase()} before submitting.`);await save('report',{id:crypto.randomUUID(),status,reason:field(f,'reason'),notes:field(f,'notes'),installed:field(f,'installed'),attachments})}}><label>Job result<select value={status} onChange={e=>{setStatus(e.target.value);setAttachments(old=>old.filter(a=>!['completion','incomplete','issue'].includes(a.kind)))}}><option>Complete</option><option>Incomplete</option></select></label><Input name="installed" label="Installation date" type="date" value={localDay()} max={localDay()} required/>{status==='Incomplete'&&<><Text label="Reason incomplete" name="reason"/>{!j.reorder&&<p className="op-callout">Reorder information must be entered by the office before the Field Supervisor can approve this INC result.</p>}</>}<Text label="Installer notes" name="notes"/>{requirements.map(kind=><label key={kind}>{reportLabels[kind]}<input type="file" multiple={kind==='issue'} accept="image/*,.pdf" disabled={busy} onChange={e=>upload(kind,Array.from(e.target.files||[]))}/><small>{attachments.filter(a=>a.kind===kind).map(a=>a.name).join(', ')||'Required'}</small></label>)}<label>Additional Photos (optional)<input type="file" multiple accept="image/*" disabled={busy} onChange={e=>upload('photos',Array.from(e.target.files||[]))}/><small>{attachments.filter(a=>a.kind==='photos').map(a=>a.name).join(', ')||'Optional'}</small></label>{busy&&<p>Uploading…</p>}{error&&<p className="op-red">{error}</p>}</Form></>}
function Quality({data,change,reload,onOpenJob}:any){const [selectedInstaller,setSelectedInstaller]=useState<any>(null);const {team,surveys,metrics,canReview,me}=data;return <><section className="op-panel"><h2>Guild Quality Scores</h2>{me.role==='admin'&&<ReportImport kind="guild" onImported={reload}/>}<p>{displayBonusDate(metrics.period.start)} – {displayBonusDate(metrics.period.end)}</p><div className="op-quality">{['Installation Crew','Quality of Workmanship','Clean & Safe','Installation Done Right'].map((c,i)=><div key={c}><span>{c}</span><strong>{metrics.categories[i]?.toFixed(2)??'—'}</strong></div>)}</div>{team.filter((m:any)=>m.role==='installer').map((m:any)=>{const rows=surveys.filter((s:any)=>s.installer_id===m.id&&s.completed_on>=metrics.period.start&&s.completed_on<=metrics.period.end);const avg=[0,1,2,3].map(i=>{const r=rows.map((s:any)=>s.ratings[i]).filter((v:any)=>v!=null);return r.length?r.reduce((sum:number,v:number)=>sum+v-1,0)/r.length:null});const q=avg.every(v=>v!==null)?avg.reduce((s:number,v:any)=>s+v,0)/4:null;return <div className="op-crew-surveys" key={m.id}><button className="op-appointment" onClick={()=>setSelectedInstaller(selectedInstaller?.id===m.id?null:m)} aria-expanded={selectedInstaller?.id===m.id} aria-controls={'surveys-'+m.id} aria-label={'View surveys for '+m.name}><strong>{m.name}</strong><QualityValue score={q}/></button>{selectedInstaller?.id===m.id&&<div id={'surveys-'+m.id}><SurveyDetails installer={m} surveys={surveys} jobs={data.jobs} period={metrics.period} onOpenJob={onOpenJob} onClose={()=>setSelectedInstaller(null)}/></div>}</div>})}</section>{canReview&&<details className="op-disclosure"><summary>Record Guild Quality survey</summary><Form resetOnSuccess onSave={async f=>change('survey',{externalId:field(f,'externalId'),customerId:field(f,'customerId'),installerId:field(f,'installerId'),completedOn:field(f,'completedOn'),ratings:[0,1,2,3].map(i=>field(f,'rating'+i)===''?null:Number(field(f,'rating'+i)))})}><Input label="Unique Guild survey reference" name="externalId" required/><Input label="Customer ID" name="customerId" required/><Select label="Installer" name="installerId" items={team.filter((m:any)=>m.role==='installer')}/><Input label="Survey completion date" name="completedOn" type="date" max={localDay()} required/>{['Installation Crew','Workmanship','Clean & Safe','Done Right'].map((v,i)=><label key={v}>{v}<select name={'rating'+i}><option value="">No response</option>{[1,2,3,4,5].map(n=><option key={n} value={n}>{n} stars</option>)}</select></label>)}<small>Original 1–5 stars. Each category is converted to 0–4 before averaging. The form clears after a successful save.</small></Form></details>}</>}
function Visits({onOpen}:any){const [rows,setRows]=useState<any[]>([]),[q,setQ]=useState(''),[error,setError]=useState('');useEffect(()=>{liveApi('/api/job-visits/recent').then(d=>setRows(d.visits)).catch(e=>setError(e.message))},[]);return <section className="op-panel"><h2>Recent job visits</h2><input aria-label="Search visits" placeholder="Search customer or job ID" value={q} onChange={e=>setQ(e.target.value)}/>{error&&<p className="op-red">{error}</p>}{rows.filter(r=>[r.job.customer,r.job.number].join(' ').toLowerCase().includes(q.toLowerCase())).map(r=><button className="op-appointment" key={r.visit.id} onClick={()=>onOpen(r.job.id)}><strong>{r.job.customer}</strong><span>{r.visit.visitedOn} · Open job visits</span></button>)}{!rows.length&&<p>No visits yet.</p>}</section>}
function Connections(){const [data,setData]=useState<any>(null),[error,setError]=useState('');const load=()=>liveApi('/api/operations/connections').then(setData).catch(e=>setError(e.message));useEffect(()=>{load()},[]);return <section className="op-panel"><h2>Connections</h2>{error&&<p role="alert" className="op-red">{error}</p>}{data&&<><p>Sales system: {data.salesIntegration}</p><p>Guild Quality: {data.guildQuality}</p><p>Email: {data.emailConfigured?'Configured':'Not configured'}</p><p>Phone push: {data.pushConfigured?'Configured':'Not configured'}</p><p>Open Settings → Photo storage to check Supabase uploads.</p><h3>Sales representative email queue</h3>{data.emails.map((e:any)=><div className="op-appointment" key={e.id}><strong>{e.recipient}<small>{e.subject}</small></strong><span>{e.status==='accepted'?'Accepted by email provider':e.status}</span>{e.status!=='accepted'&&<button onClick={async()=>{try{await liveApi('/api/operations',{action:'retryEmail',id:e.id});load()}catch(err){setError((err as Error).message)}}}>Retry</button>}</div>)}</>}</section>}
function ProjectRecord({j}:any){const [data,setData]=useState<any>(null),[editing,setEditing]=useState(false),[error,setError]=useState('');const load=()=>liveApi('/api/customer-records?jobId='+j.id).then(setData).catch(e=>setError(e.message));useEffect(()=>{load()},[j.id]);const fields=[...new Map([...recordFields,...profileFields,...historyDateFields].map(v=>[v[0],v])).values()].filter(([k])=>!k.startsWith('permit')&&k!=='inspectionDate');return <>{error&&<p className="op-red">{error}</p>}{data&&<><p className="op-muted">Imported customer record. Its historical balance fields do not replace the operational amount due.</p>{j.importSource&&<p className="op-callout">Imported from {j.importSource.file}, page {j.importSource.page}. Names and notes may be clipped in the source. Missing address, permit, product breakdown and assignments need review. {j.stage==='Incomplete'&&!j.incompleteSince?'INC entry date is unconfirmed; excluded from aged totals until verified.':''}</p>}{data.canEdit&&<button className="live-button" onClick={()=>setEditing(!editing)}>Update record</button>}{editing?<Form onSave={async f=>{const record={...data.record};fields.forEach(([k])=>record[k]=field(f,k));await liveApi('/api/customer-records',{jobId:j.id,version:data.version,record});await load();setEditing(false)}}>{fields.map(([k,label])=><Input key={k} name={k} label={label} value={data.record[k]}/>)}</Form>:<dl className="live-record">{fields.filter(([k])=>data.record[k]).map(([k,label])=><div key={k}><dt>{label}</dt><dd>{displayDate(data.record[k])}</dd></div>)}</dl>}{data.canEdit&&<Form onSave={async f=>{await liveApi('/api/customer-records',{jobId:j.id,version:data.version,note:field(f,'note'),kind:'Contact'});await load()}}><Text name="note" label="Add contact note"/></Form>}{data.events.map((e:any)=><p className="op-history" key={e.id}>{e.note}<small>{e.actor_name} · {displayDate(e.created)}</small></p>)}</>}</>}

function PaymentForm({j,save}:any){const [mode,setMode]=useState('payment');return <Form onSave={async f=>save(mode,{...(mode==='payment'?{paymentAmount:Number(field(f,'amount'))}:{amount:Number(field(f,'amount'))}),paymentType:field(f,'paymentType')})}><p>Current balance due: {currency(j.amount)}</p><label>Action<select value={mode} onChange={e=>setMode(e.target.value)}><option value="payment">Record payment</option><option value="balance">Reconcile balance from main system</option></select></label><Input key={mode} name="amount" label={mode==='payment'?'Payment amount':'Correct balance due'} type="number" min={mode==='payment'?'.01':'0'} max={mode==='payment'&&j.amount!=null?j.amount:undefined} step=".01" required/>{mode==='payment'&&<Select name="paymentType" label="Payment type" value={j.paymentMethod} items={paymentMethods}/>}</Form>}
function InstallerQualitySurveys({data,onOpenJob}:any){
 const [open,setOpen]=useState(false),{me,surveys,metrics,jobs}=data;
 return <section className="live-installer-quality" aria-label="My Guild Quality"><div className="op-metrics live-installer-score"><button type="button" onClick={()=>setOpen(!open)} aria-expanded={open} aria-controls="installer-survey-results" aria-label="View my individual survey scores"><span>Guild Quality</span><strong><QualityValue score={metrics.score}/></strong><small>{metrics.surveys} surveys in period</small></button></div>{open&&<div id="installer-survey-results"><SurveyDetails installer={me} surveys={surveys} jobs={jobs} period={metrics.period} onOpenJob={onOpenJob} onClose={()=>setOpen(false)}/></div>}</section>
}

function LinkedAccounts({j,jobs,canEdit,save,onOpen}:any){
 const [query,setQuery]=useState('');
 const linked=jobs.filter((v:any)=>v.id!==j.id&&(j.linkedAccountIds||[]).includes(v.id));
 const candidates=jobs.filter((v:any)=>v.id!==j.id&&!(j.linkedAccountIds||[]).includes(v.id)&&`${v.number} ${v.customer} ${v.address}`.toLowerCase().includes(query.trim().toLowerCase()));
 return <details className="op-disclosure"><summary>Linked customer accounts ({linked.length})</summary><p>Link separate jobs for the same customer. Linking copies the selected account’s customer details, permits, sales information and notes into this job. Admin and PA also copy payment method and amounts. Review the source before linking. Products, schedules and statuses stay separate.</p>{linked.map((v:any)=><div key={v.id}><button type="button" className="live-button" onClick={()=>onOpen(v.id)}>#{v.number} · {v.customer} · {v.product}</button>{canEdit&&<Form onSave={async()=>save('linkAccount',{targetId:v.id})} submitLabel="Copy account information again">{null}</Form>}{canEdit&&<Form onSave={async()=>save('unlinkAccount',{targetId:v.id})} submitLabel="Unlink account">{null}</Form>}</div>)}{canEdit&&<Form onSave={async(f:FormData)=>save('linkAccount',{targetId:field(f,'targetId')})} submitLabel="Link & copy account information"><label>Find account by customer ID, name or address<input value={query} onChange={e=>setQuery(e.target.value)}/></label><Select label="Account for the same customer" name="targetId" items={candidates.map((v:any)=>({id:v.id,name:`#${v.number} · ${v.customer} · ${v.product} · ${v.address}`}))}/></Form>}</details>
}

function JobPhotoUpload({j,save}:any){
 const [kind,setKind]=useState<string>('photos'),[photos,setPhotos]=useState<any[]>([]),[busy,setBusy]=useState(false),[error,setError]=useState(''),[saved,setSaved]=useState(false);
 return <section className="live-completion"><h3>Add job photos</h3><p>Save photos without submitting a completion report or changing job status.</p><Form submitLabel="Save job photos" onSave={async()=>{if(busy)throw Error('Wait for uploads to finish.');if(!photos.length)throw Error('Select at least one photo.');await save('jobPhotos',{attachments:photos});setPhotos([]);setSaved(true)}}><label>Photo category<select value={kind} disabled={busy} onChange={e=>setKind(e.target.value)}>{jobPhotoKinds.map(v=><option key={v} value={v}>{reportLabels[v]}</option>)}</select></label><label>Job photos<input type="file" multiple accept="image/*" disabled={busy} onChange={async e=>{const files=Array.from(e.target.files||[]);e.target.value='';if(!files.length)return;setBusy(true);setError('');setSaved(false);try{for(const file of files){const a=await uploadAttachment(j.id,kind,file);setPhotos(old=>[...old,a]);}}catch(e){setError((e as Error).message)}finally{setBusy(false)}}}/></label>{photos.map(a=><p key={a.key}>{a.name} · {reportLabels[a.kind as keyof typeof reportLabels]} <button type="button" disabled={busy} onClick={()=>setPhotos(old=>old.filter(v=>v.key!==a.key))}>Remove</button></p>)}{busy&&<p>Uploading…</p>}{error&&<p role="alert" className="op-red">{error}</p>}{saved&&<p role="status">✓ Job photos saved.</p>}</Form></section>
}
